package pe.animetv;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import okhttp3.*;import okhttp3.mockwebserver.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class SourceHttpTest {
 @Test public void supersededRequestCancelsSocketPromptly()throws Exception{MockWebServer server=new MockWebServer();server.start();OkHttpClient client=new OkHttpClient.Builder().readTimeout(60,TimeUnit.SECONDS).build();ExecutorService worker=Executors.newSingleThreadExecutor();CountDownLatch stopped=new CountDownLatch(1);AtomicReference<Throwable> failure=new AtomicReference<>();try{server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));Future<?> task=worker.submit(()->{try{SourceHttp.get(client,new Request.Builder().url(server.url("/slow")).build(),"test");}catch(Exception e){failure.set(e);}finally{stopped.countDown();}});assertNotNull(server.takeRequest(3,TimeUnit.SECONDS));task.cancel(true);assertTrue(stopped.await(3,TimeUnit.SECONDS));assertTrue(failure.get().getMessage().contains("cancelada"));}finally{worker.shutdownNow();client.dispatcher().cancelAll();server.shutdown();client.connectionPool().evictAll();client.dispatcher().executorService().shutdownNow();}}
 @Test public void statusAndBodyRemainAvailableForCloudflareDecision()throws Exception{MockWebServer server=new MockWebServer();server.start();OkHttpClient client=new OkHttpClient();try{server.enqueue(new MockResponse().setResponseCode(403).setBody("cf-chl challenge-platform"));var page=SourceHttp.page(client,new Request.Builder().url(server.url("/")).build());assertEquals(403,page.code());assertTrue(ProtectedPages.challenge(page.code(),page.body()));}finally{server.shutdown();client.dispatcher().executorService().shutdownNow();client.connectionPool().evictAll();}}
}
